CREATE TABLE ctac_range4 (id int, d date NOT NULL) PARTITION BY RANGE (d);
CREATE TABLE ctac_range4_p1 PARTITION OF ctac_range4 FOR VALUES FROM (MINVALUE) TO ('2021-01-01');
CREATE TABLE ctac_range4_p2 PARTITION OF ctac_range4 FOR VALUES FROM ('2021-01-01') TO (MAXVALUE)

CREATE TABLE ctac_hash2 (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE ctac_hash2_p0 PARTITION OF ctac_hash2 FOR VALUES WITH (MODULUS 4, REMAINDER 0);
CREATE TABLE ctac_hash2_p1 PARTITION OF ctac_hash2 FOR VALUES WITH (MODULUS 4, REMAINDER 1)

CREATE TABLE ctac_hash4 (id int NOT NULL) PARTITION BY HASH (id);
CREATE TABLE ctac_hash4_p0 PARTITION OF ctac_hash4 FOR VALUES WITH (MODULUS 2, REMAINDER 0);
CREATE TABLE ctac_hash4_p1 PARTITION OF ctac_hash4 FOR VALUES WITH (MODULUS 2, REMAINDER 1)

CREATE TABLE ctac_range_int (id int, n int) PARTITION BY RANGE (n);
CREATE TABLE ctac_range_int_p1 PARTITION OF ctac_range_int FOR VALUES FROM (1) TO (100);
CREATE TABLE ctac_range_int_p2 PARTITION OF ctac_range_int FOR VALUES FROM (100) TO (200)

CREATE TABLE ctac_part_default_bad (id int, d date) PARTITION BY RANGE (d);
CREATE TABLE ctac_part_default_bad_p1 PARTITION OF ctac_part_default_bad DEFAULT;
CREATE TABLE ctac_part_default_bad_p2 PARTITION OF ctac_part_default_bad DEFAULT

CREATE TABLE ctac_range9 (id int, d date) PARTITION BY RANGE (d);
CREATE TABLE ctac_range9_sub (id int, d date) PARTITION BY RANGE (d);
CREATE TABLE ctac_range9_sub_p1 PARTITION OF ctac_range9_sub FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
ALTER TABLE ctac_range9 ATTACH PARTITION ctac_range9_sub FOR VALUES FROM ('2024-01-01') TO ('2025-01-01')

CREATE TABLE ctac_range10 (id int, d date) PARTITION BY RANGE (d);
CREATE TABLE ctac_range10_p1 PARTITION OF ctac_range10 FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE ctac_range10_sub PARTITION OF ctac_range10 FOR VALUES FROM ('2025-01-01') TO ('2026-01-01') PARTITION BY LIST (id)

CREATE TABLE ctac_range_tz (id int, ts timestamptz NOT NULL) PARTITION BY RANGE (ts);
CREATE TABLE ctac_range_tz_p1 PARTITION OF ctac_range_tz FOR VALUES FROM (MINVALUE) TO ('2024-01-01 00:00:00+00');
CREATE TABLE ctac_range_tz_p2 PARTITION OF ctac_range_tz FOR VALUES FROM ('2024-01-01 00:00:00+00') TO (MAXVALUE)

CREATE TABLE ctac_list5 (id int, code int) PARTITION BY LIST (code);
CREATE TABLE ctac_list5_p1 PARTITION OF ctac_list5 FOR VALUES IN (1, 2, 3);
CREATE TABLE ctac_list5_p2 PARTITION OF ctac_list5 FOR VALUES IN (4, 5, 6);
CREATE TABLE ctac_list5_def PARTITION OF ctac_list5 DEFAULT

